arguments.content:
*{box-sizing:border-box}
body{margin:0;font-family:Georgia,'Times New Roman',serif;line-height:1.55;color:#22201c;background:#fbf8f3}
.wrap{max-width:1040px;margin:0 auto;padding:0 20px}
header.hero{padding:40px 0 32px;background:#f6e3ea}
h1{font-size:2rem;line-height:1.15;margin:0 0 12px}
h2{font-size:1.5rem;line-height:1.2;margin:0 0 12px}
section{padding:36px 0;border-top:1px solid #e6dfd4}
.lead{font-size:1.1rem;max-width:36em;margin:0 0 20px}
.cta{display:inline-block;padding:14px 22px;border-radius:10px;background:#9b3b5a;color:#fff;text-decoration:none;font-weight:600;border:2px solid #9b3b5a}
.cta:hover{background:#fff;color:#9b3b5a}
.cta:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #f2b84b;outline-offset:2px}
.grid{display:grid;gap:16px}
.card{background:#fff;border-radius:12px;padding:16px}
dt{font-weight:600;margin-top:12px}
dd{margin:4px 0 0}
form{display:grid;gap:12px;max-width:440px}
label{display:grid;gap:4px}
input{font:inherit;padding:10px 12px;border:1px solid #b9b0a3;border-radius:8px;width:100%}
input[aria-invalid=true]{border-color:#b3261e}
.error{color:#b3261e;font-size:.95rem;min-height:1.2em;margin:0}
.ok{color:#1b6b3a;font-weight:600}
button{font:inherit;padding:12px 18px;border-radius:10px;border:0;background:#9b3b5a;color:#fff;cursor:pointer}
button:disabled{opacity:.6;cursor:progress}
footer{padding:28px 0;background:#22201c;color:#f3efe8}
footer a{color:#f3efe8}
@media (min-width:768px){h1{font-size:3rem}.grid{grid-template-columns:repeat(3,1fr)}}

const form = document.getElementById("order");
const phone = document.getElementById("phone");
const name = document.getElementById("name");
const error = document.getElementById("error");
const done = document.getElementById("done");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const problems = [];
  if (!name.value.trim()) problems.push("Напишите, как к вам обращаться.");
  if (!/^\+?[\d\s()-]{10,}$/.test(phone.value.trim())) problems.push("Проверьте номер телефона.");
  name.setAttribute("aria-invalid", String(!name.value.trim()));
  phone.setAttribute("aria-invalid", String(problems.length > 0 && !/^\+?[\d\s()-]{10,}$/.test(phone.value.trim())));
  error.textContent = problems.join(" ");
  if (problems.length) return;
  done.hidden = false;
  form.reset();
});
